            sb.append("    <li><strong>")
              .append(escapeHtml(entry.getKey()))
              .append("</strong>: ")
              .append(escapeHtml(entry.getValue()))
              .append("</li>\n");
        }

        sb.append("  </ul>\n")
          .append("  <a href=\"/\">Submit another form</a>\n")
          .append("</body>\n")
          .append("</html>");

        return sb.toString();
    }

    private static String escapeHtml(String text) {
        if (text == null) {
            return "";
        }

        return text.replace("&", "&amp;")
                   .replace("<", "&lt;")
                   .replace(">", "&gt;")
                   .replace("\"", "&quot;")
                   .replace("'", "&#39;");
    }
